INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_CIV','The Shattered Empire');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_SHORT','Shattered Empire');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_ADJECTIVE','Imperial');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEADER','The Last Emperor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_TRAIT','The Weight of an Empire');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_TRAIT_HELP','Begin with 82 Imperial Authority, a population-2 capital and two provinces (or Settlers where safe founding is unavailable). Every province has a persistent Governor. Govern Loyalty, military Oaths, reforms and succession to avert civil wars. Survive collapse and restore unity to earn +10% Production and Culture while stable. Open Imperial Administration near the top panel.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_CIV_PEDIA','Conquering the world was never the difficult part. Keeping it was.[NEWLINE][NEWLINE]Aeternum once ruled a world of marble avenues, provincial palaces and legions sworn to the Eternal Throne. Victory brought distant lands into the imperial order, but each Governor acquired estates, clients and soldiers. The Last Emperor inherits the symbols of eternity and the practical burden of persuading powerful people to keep their promises.[NEWLINE][NEWLINE]This fictional civilization tells its history through the Governors appointed, soldiers lost, Emperors chosen, and provinces restored in each campaign. Collapse is avoidable: a loyal, ambitious Governor can remain an invaluable ally.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEADER_PEDIA','The Last Emperor is the permanent diplomatic face of the Eternal Throne. Individual rulers succeed one another inside Imperial Administration, where their reigns, relationships and achievements survive saving and loading. The monarch must balance the hereditary court, the armies, and the provincial council.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_STRATEGY','Three early cities and strong Imperial Legions reward expansion, but sustained growth strains administration. Garrison provinces, connect them to Aeternum and construct Governor Palaces. Complete demands before deadlines and manage ambitious Governors before they organize a civil war. Choose reforms and successors that address your weakest institution. Military suppression, autonomy and reconciliation can all end rebellions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DAWN','Last Emperor, the Eternal Throne is yours. Aeternum and two provinces await your command. Your Legions can conquer kingdoms; your Governors can keep them prosperous or tear them apart. Rule wisely, listen before resentment hardens, and make the shattered crown whole again.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEGION','Imperial Legion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEGION_HELP','Replaces the Warrior. Strength 10; costs 15% more (rounded up). Imperial Discipline grants +15% Combat Strength in friendly territory while Authority is at least 60. Discipline survives upgrades. Participates in provincial Oaths and bounded crisis defections.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEGION_PEDIA','The Imperial Legion carries the eagle of Aeternum and an oath to the Eternal Throne. Training binds the cohort to its recruiting province; service and victory strengthen its allegiance, while a rebellious home Governor may threaten it. Its inherited discipline endures when its weapons change.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LEGION_STRATEGY','Use the Legion to defend exposed early provinces. Maintain Authority above 60 for its friendly territory bonus. A veteran with a weak Oath and a rebellious home province may defect; keep provincial loyalty high.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_PALACE','Provincial Governor''s Palace');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_PALACE_HELP','Replaces the Monument, retaining all normal costs and effects. +1 Gold. In provinces: +2 Loyalty each political interval and permits autonomy charters. In the capital: +1 Authority every ten Standard-speed turns. Effects scale in timing with game speed.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_PALACE_PEDIA','The Palace combines the public monuments of imperial memory with the offices of provincial rule. Tax accounts, petitions and military rolls pass through its halls. Its strength rests in trusted administration, not merely marble walls.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_PALACE_STRATEGY','Build early in provinces to support Loyalty and unlock autonomy. The capital Palace provides measured Authority recovery. Provincial administration costs 1 Gold per city regardless of the Palace.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DUMMY','Imperial administration effect');
