INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_SUCCESSION_TITLE','The Imperial Council');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_SUCCESSION_NOTICE','Three persistent candidates seek the Eternal Throne. Choose in the Dynasty tab before the deadline; otherwise the Council selects an appropriate heir.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_BLOOD','Heir of Blood');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_STEEL','Heir of Steel');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_COUNCIL','Council''s Choice');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_COUNCIL_RELATION','Provincial council');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_HELP_BLOOD','+15 Authority. Ambitious Governors lose 10 Loyalty. Peaceful succession adds another +5 Authority.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_HELP_STEEL','+15 military Oath. Merchant and Populist Governors lose 10 Loyalty. Peaceful succession adds +5 Authority.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_HELP_COUNCIL','+10 provincial Loyalty, -15 Authority, and -10% city Production for ten Standard-speed turns. Peaceful succession adds +5 Authority.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_TRAIT_BLOOD','Hereditary legitimacy');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_TRAIT_STEEL','Veteran commander');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_TRAIT_COUNCIL','Consensus builder');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HEIR_TRAIT_FOUNDER','Keeper of the fractured crown');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REFORM_HELP_MONARCHY','+10% military Production in the capital. Suppression yields +7 Authority instead of +5. Distant provinces lose another 2 Loyalty per interval. Rebel recruitment budgets increase by 1.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REFORM_HELP_FEDERATION','+3 Loyalty per interval in chartered provinces and fewer demands. Chartered provinces lose 10% Production. Administrative capacity increases by three cities.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REFORM_HELP_DICTATORSHIP','+15 effective Oath to disciplined Legion lineages while active. +10% Combat Strength against barbarian units, including rebels. Militarist Governor Ambition grows faster.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REFORM_COST','Costs 10 Authority; changes have a 30 Standard-speed turn cooldown. Unlocks in the Classical Era.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REPLACE_COST','Costs 8 Authority. Replacement creates one turn of resistance and reduces local military Oaths by 5.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_CHARTER_COST','Peacetime: 50% provincial Gold cost and 5 Authority; +15 Loyalty, +12 Ambition and permanent autonomy. Requires a Palace and loyal or discontented administration.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_SETTLEMENT_COST','Wartime: 200% provincial Gold cost and 10 Authority. Ends this faction only, guarantees at least 70 Loyalty, adds 20 Ambition and permanent autonomy. Hereditary privileges add 0.5 Ambition each political interval, including after Governor replacement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_AUTHORITY_LABEL','Authority');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_ACTION_SETTLEMENT','Negotiate wartime autonomy');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_HISTORY_DEMAND_CANCELLED','The petition of {1_Name} was withdrawn because it was no longer feasible: {2_Demand}. No political penalty applied.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_RECONCILE_COST','Costs 15 Authority; ends the local revolt and rebuilds loyalty.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_REBELLION_REQUIRED','An active provincial rebellion is required.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_AUTHORITY_REQUIRED','Insufficient Imperial Authority.');
