INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_PROMO_HELP_REBEL_COMBAT','+10% Combat Strength against barbarians, including political rebel armies.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_RESTORED_TITLE','The Empire Reborn');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_RESTORED_NOTICE','+10% Production and Culture in all imperial cities while stable. Renewed political crisis makes these effects dormant.');
