INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_GOVERNOR_DETAIL','{1_City}[NEWLINE]{2_Name}, {3_Archetype}[NEWLINE]Loyalty {4_Loyalty} | Ambition {5_Ambition} | Prestige {6_Prestige}[NEWLINE]{7_Stage}');
