INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_LOYALTY_CHANGE','Last interval Loyalty change: {1_Amount} (routine movement capped at +/-8)');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DEMAND_DETAIL','Petition: {1_Demand}[NEWLINE]Deadline: turn {2_Turn}; financial compensation: {3_Cost} Gold');
