INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DEMAND_LOCATION','Target plot: {1_X}, {2_Y}');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DECISION_HELP','Only currently valid actions are shown. Replacements cost Authority; payments scale with population, income and speed. Decisions have cooldowns. Ambition and Prestige alone never cause rebellion.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_OVERVIEW_DETAIL','Loyal provinces: {1_Loyal} | Discontented: {2_Unrest} | Rebel: {3_Rebels}[NEWLINE]Administrative strain: {4_Strain} | Average Loyalty: {5_Loyalty}[NEWLINE]War duration pressure: {6_Turns} turns');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_OVERVIEW_HELP','Loyalty below 45 causes discontent; below 25 causes defiance. Two critical political checks can trigger revolt. Authority below 30 and three nearby severe provinces with an ambitious claimant can produce a War of the Crowns. Administration capacity is 5 + twice your era, with three extra under Federation.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_WAR_DETAIL','{1_War}[NEWLINE]Claimant: {2_Leader}; began turn {3_Turn}[NEWLINE]Provinces: {4_Count}; rebel troops raised: {5_Troops}; defections: {6_Defections}');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_WAR_RECORD','{1_War}: claimant {2_Leader}[NEWLINE]Turns {3_Start}-{4_End}: {5_Result}[NEWLINE]Provinces restored {6_Count}; troops raised {7_Troops}; Authority lost {8_Lost}, recovered {9_Recovered}');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_RESTORATION_DETAIL','Restoration: {1_State}[NEWLINE]Qualifying stability: {2_Progress}/{3_Required} turns. Requires a resolved collapse, Authority 75, average Loyalty 80, no revolt or pending succession.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_SUCCESSION_PENDING','The Council awaits a successor. Decision deadline: turn {1_Turn}.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_MILITARY_OVERVIEW','Tracked land regiments: {1_Count}; average Oath: {2_Oath}');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_MILITARY_HELP','Oaths follow home-province Loyalty and Authority. Defections require a political rebellion and Oath below 40, are limited to two per faction, and exclude foreign mod uniques, civilians, cargo, embarked troops and units in cities. An equivalent rebel is created safely before a defector is removed.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_CAPITAL_ARMY','Central imperial army');
