INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_FIRST_GREETING','Behold the Eternal Throne. Kingdoms rise and fall, but our Empire shall endure. Do you come as a friend, or as another enemy seeking our ruins?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_DEFEATED','The banners have fallen. The Legions have scattered. Yet remember this, conqueror: even shattered empires leave shadows upon the earth.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_DECLAREWAR','Our Legions will settle what your envoys could not. Let the imperial eagles advance.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_ATTACKED','You strike at the Throne while our provinces watch. You shall learn what still binds this Empire.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_PEACE_MADE_BY_HUMAN_GRACIOUS','Let our peoples rest. Even an Emperor must know when to sheathe the sword.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_TRADE_ACCEPT_ACCEPTABLE','The imperial treasury accepts these terms.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_IMPERIAL_DIPLO_TRADE_REJECT_UNACCEPTABLE','Such terms would make every Governor laugh at the Throne. Present a fairer offer.');
