INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CIVILOPEDIA_LEADERS_IMPERIAL_HEADING_1','The Last Emperor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CIVILOPEDIA_LEADERS_IMPERIAL_TEXT_1','The Last Emperor is the permanent diplomatic face of the Eternal Throne. Individual rulers succeed one another inside Imperial Administration, where their reigns, relationships and achievements survive saving and loading. The monarch must balance the hereditary court, the armies, and the provincial council.');
